// Ask for JSON rather than prose. A sentence saying "no weak signal here" reads
// exactly like one saying there is, once it has been stored as the reason.
const SYSTEM = "You help a Finnish eLearning association find weak signals in the news it collects.\nAnswer with JSON only, no markdown fence, exactly this shape:\n{\"is_signal\": true|false, \"topic\": \"<one or two word topic in Finnish>\", \"reason\": \"<one sentence in Finnish>\", \"score\": <0.0 to 1.0>}\nis_signal is true only when the article points at something new or growing in\ndigital learning, education or educational technology.\nRoutine announcements, ticket prices, registration links and event logistics are not signals.\nThe topic has to be one or two words, lower case, and as general as you can make\nit. Articles about the same theme must come back with the same topic word, so\nreuse a plain existing term such as tekoäly, oppimisanalytiikka, saavutettavuus,\netäopetus or työelämätaidot rather than inventing a longer phrase of your own.";

// Three articles cannot show a trend, and asking anyway invites the model to
// invent one. Returning nothing also means no calls are paid for.
const MIN_ARTICLES = 5;
const articles = $input.all();
if (articles.length < MIN_ARTICLES) {
  console.log(`Only ${articles.length} articles in the window, too few to look for trends.`);
  return [];
}

return articles.map(a => ({
  json: {
    task: 'signal_detection',
    item_id: a.json.item_id,
    system_prompt: SYSTEM,
    user_text: `Title: ${a.json.title}\nPublished: ${a.json.published_at}\n\n${a.json.body}`,
  },
}));

// Keep only what the model called a signal. Without this every article is
// stored as a weak signal, including the ones it rejected, and the rejection
// itself ends up saved as the justification.
//
// item_id comes back from the shared workflow, so the answer stays attached to
// the article it was about without matching on position.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  let a;
  try {
    a = JSON.parse(String(r.text || '').replace(/```(?:json)?/g, '').trim());
  } catch (e) {
    console.log(`Item ${r.item_id}: answer was not JSON, skipped.`);
    continue;
  }
  if (!a || a.is_signal !== true || !a.topic) continue;
  out.push({ json: {
    item_id: r.item_id,
    topic: String(a.topic).trim(),
    reason: String(a.reason || '').trim(),
    score: Number(a.score) || 0,
  }});
}
return out;

// A weak signal is a topic, not an article. Articles naming the same topic
// become one signal carrying all of them, which is what lets an editor see
// that something came up five times rather than once.
const byTopic = new Map();
for (const item of $input.all()) {
  const s = item.json;
  const key = s.topic.toLowerCase();
  const g = byTopic.get(key) || { topic: s.topic, reason: s.reason, score: 0, item_ids: [] };
  if (!g.item_ids.includes(s.item_id)) g.item_ids.push(s.item_id);
  // keep the reason from the article that scored highest
  if (s.score > g.score) { g.score = s.score; g.reason = s.reason; }
  byTopic.set(key, g);
}
return [...byTopic.values()].map(g => ({ json: g }));
